steps.script:
$o=@{state='pending'}
try{
 $p=@(Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" | Where-Object { [string]$_.CommandLine -match 'TTiTTularesDedicatedListener[.]ps1' })
 if($p.Count -gt 2){throw 'TOO_MANY_LISTENERS'}
 foreach($q in $p){Stop-Process -Id $q.ProcessId -Force -ErrorAction Stop}
 Start-ScheduledTask -TaskName 'TTiTTulares Local' -ErrorAction Stop
 $o.state='listener_restarted';$o.stopped=$p.Count
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
